#include<bits/stdc++.h>

using namespace std;

void solve()
{
int x, y;
cin >> x >> y;
int s = x + y;
for(int d = (1 << 30); d >= 1; d >>= 1)
if((s & d) != 0 && x >= d)
x -= d;
cout << s << " " << x << endl;
}

int main()
{
ios_base::sync_with_stdio(0);
cin.tie(0);
int t;
cin >> t;
for(int i = 0; i < t; i++)
solve();
}

